&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de magus&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_magus_0&quot; href=&quot;#Les_arch&#233;types_de_magus_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Occulte-(Magus).html&quot; title=&quot;Archer occulte&quot;&gt;Archer occulte&lt;/a&gt; (HOTS)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;l&#233;mentaire-(Magus).html&quot; title=&quot;Chevalier &#233;l&#233;mentaire (magus)&quot;&gt;Chevalier &#233;l&#233;mentaire&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Suli-(Race).html&quot; title=&quot;Les sulis&quot;&gt;Suli&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Danse-Sort-(Magus).html&quot; title=&quot;Danse-sort&quot;&gt;Danse-sort&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-De-La-Tour-(Magus).html&quot; title=&quot;D&#233;fenseur de la tour&quot;&gt;D&#233;fenseur de la tour&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;corcheur-Fi&#233;lon-(Magus).html&quot; title=&quot;&#201;corcheur fi&#233;lon&quot;&gt;&#201;corcheur fi&#233;lon&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tieffelin-(Race).html&quot; title=&quot;Les tieffelins&quot;&gt;Tieffelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;sot&#233;riste-(Magus).html&quot; title=&quot;&#201;sot&#233;riste&quot;&gt;&#201;sot&#233;riste&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forge&#226;me-(Magus).html&quot; title=&quot;Forge&#226;me&quot;&gt;Forge&#226;me&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;Kensai&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lameli&#233;-(Magus).html&quot; title=&quot;Lameli&#233;&quot;&gt;Lameli&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesprit-(Magus).html&quot; title=&quot;Lamesprit&quot;&gt;Lamesprit&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lamesort-(Magus).html&quot; title=&quot;Lamesort&quot;&gt;Lamesort&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lanceur-De-Mal&#233;fices-(Magus).html&quot; title=&quot;Lanceur de mal&#233;fices&quot;&gt;Lanceur de mal&#233;fices&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mage-De-Bataille-Blind&#233;-(Magus).html&quot; title=&quot;Mage de bataille blind&#233;&quot;&gt;Mage de bataille blind&#233;&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Myrmidarque-(Magus).html&quot; title=&quot;Myrmidarque&quot;&gt;Myrmidarque&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-&#201;trange-(Magus).html&quot; title=&quot;Rejeton &#233;trange&quot;&gt;Rejeton &#233;trange&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Skirnir-(Magus).html&quot; title=&quot;Skirnir&quot;&gt;Skirnir&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-B&#226;ton-(Magus).html&quot; title=&quot;Sp&#233;cialiste du b&#226;ton&quot;&gt;Sp&#233;cialiste du b&#226;ton&lt;/a&gt; (AM)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;. Le kensai passe sa vie &#224; s’entra&#238;ner et &#224; m&#233;diter pour atteindre la pl&#233;nitude &#224; travers le maniement parfait d’une arme, g&#233;n&#233;ralement une &#233;p&#233;e, qu’il utilise pour canaliser sa puissance magique lors d’une danse mortelle et &#233;poustouflante qui d&#233;passe les aptitudes des meilleurs guerriers.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et armures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_armures_0&quot; href=&quot;#Armes_et_armures_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le kensai est form&#233; au maniement des &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armecourante.html&quot; title=&quot;arme courante&quot;&gt;armes courantes&lt;/a&gt; et d’une unique &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedeguerre.html&quot; title=&quot;arme de guerre&quot;&gt;arme de guerre&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armeexotique.html&quot; title=&quot;arme exotique&quot;&gt;exotique&lt;/a&gt; de son choix. Il n’est pas form&#233; au port des armures ni au maniement du bouclier et subit les risques habituels d’&#233;chec des sorts profanes quand il lance des sorts de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magus&lt;/a&gt; en armure.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arme de pr&#233;dilection (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Arme_de_pr&#233;dilection_Ext_1&quot; href=&quot;#Arme_de_pr&#233;dilection_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Guerre.html#7&quot; title=&quot;FAQ de l&amp;#39;Art de la guerre&quot;&gt;→&lt;/a&gt; Magus, Kensai : Plusieurs capacit&#233;s du kensai font r&#233;f&#233;rence &#224; &#171; son arme de pr&#233;dilection &#187;. Est-ce l’&#171; unique arme de guerre ou exotique de son choix &#187; de la capacit&#233; armes et armures ? Sinon, comment dois-je choisir son arme de pr&#233;dilection effective ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;L’arme de pr&#233;dilection fait en effet r&#233;f&#233;rence &#224; l’unique arme de guerre ou exotique qu’il choisit. &lt;i&gt;(Retour &#224; l’&lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Kensai-(Magus).html&quot; title=&quot;Kensai&quot;&gt;arch&#233;type&lt;/a&gt;&lt;/u&gt;)&lt;/i&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Au niveau 1, le kensai gagne &lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; comme don suppl&#233;mentaire pour l’arme de son choix.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation r&#233;duite&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_r&#233;duite_2&quot; href=&quot;#Incantation_r&#233;duite_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le kensai lance un sort de moins de chaque niveau de sort que les &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magi&lt;/a&gt; ordinaires. Si ce changement fait passer son nombre de sorts &#224; 0, il peut lancer des sorts de ce niveau uniquement si son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; lui accorde des sorts suppl&#233;mentaires pour ce niveau.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;D&#233;fense astucieuse (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;D&#233;fense_astucieuse_Ext_3&quot; href=&quot;#D&#233;fense_astucieuse_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, quand le kensai manie son arme de pr&#233;dilection, il gagne le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Duelliste.html#DEFENSEASTUCIEUSE&quot; title=&quot;Le duelliste&quot;&gt;d&#233;fense astucieuse&lt;/a&gt;. Il fonctionne comme le pouvoir de la classe de prestige &lt;a class=&quot;pagelink&quot; href=&quot;Duelliste.html&quot; title=&quot;Le duelliste&quot;&gt;duelliste&lt;/a&gt; mais son arme de pr&#233;dilection peut &#234;tre de n’importe quel type.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Coup parfait (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Coup_parfait_Ext_4&quot; href=&quot;#Coup_parfait_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, quand le kensai touche une cible avec son arme de pr&#233;dilection, il peut d&#233;penser 1 point de sa &lt;a class=&quot;pagelink&quot; href=&quot;Magus#Reservemagique.html&quot; title=&quot;r&#233;serve magique&quot;&gt;r&#233;serve magique&lt;/a&gt; pour optimiser les d&#233;g&#226;ts. Il ne lance pas les d&#233;s, l’arme inflige automatiquement les d&#233;g&#226;ts maximaux. Ce pouvoir affecte uniquement les d&#233;s de d&#233;g&#226;ts de base, pas les d&#233;g&#226;ts suppl&#233;mentaires d’une &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaque sournoise&lt;/a&gt;, des propri&#233;t&#233;s magiques d’une arme, d’une &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#FRAPPEMAGIQUE&quot; title=&quot;Le magus&quot;&gt;frappe magique&lt;/a&gt; ou d’un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt;. Si le kensai confirme un coup critique, il peut &#224; la place d&#233;penser 2 points pour augmenter le multiplicateur de critique de 1. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;souvenir magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Entra&#238;nement de guerrier (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Entra&#238;nement_de_guerrier_Ext_5&quot; href=&quot;#Entra&#238;nement_de_guerrier_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; partir du niveau 7, le kensai consid&#232;re qu’il a un niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; &#233;gal &#224; son niveau de magus -3 quand il s’agit de remplir des conditions requises (s’il poss&#232;de des niveaux de guerrier, ils se cumulent). Il ne peut pas profiter des avantages de ces dons avec autre chose que son arme de pr&#233;dilection. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#RESERVEDECONNAISSANCES&quot; title=&quot;Le magus&quot;&gt;r&#233;serve de connaissances&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Iaijutsu (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Iaijutsu_Ext_6&quot; href=&quot;#Iaijutsu_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 7, le kensai applique son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; en plus de son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; ses tests d’&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; (0 au minimum). Le kensai peut faire une &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt; quand il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Prisaud&#233;pourvu.html&quot; title=&quot;Pris au d&#233;pourvu&quot;&gt;pris au d&#233;pourvu&lt;/a&gt; et peut d&#233;gainer son arme de pr&#233;dilection par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Libre.html&quot; title=&quot;Action libre&quot;&gt;action libre&lt;/a&gt; lors de cette attaque. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ARMUREINTERMEDIAIRE&quot; title=&quot;Le magus&quot;&gt;armure interm&#233;diaire&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Perfection critique (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Perfection_critique_Ext_7&quot; href=&quot;#Perfection_critique_Ext_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le kensai ajoute son bonus d’Intelligence (0 au minimum) &#224; ses jets de confirmation de &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; avec son arme de pr&#233;dilection. De plus, il utilise ses niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html&quot; title=&quot;Le magus&quot;&gt;magus&lt;/a&gt; au lieu de son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;bonus de base &#224; l’attaque&lt;/a&gt; quand il s’agit de savoir s’il remplit les conditions requises pour &lt;a class=&quot;pagelink&quot; href=&quot;Don-Pour-Les-Critiques.html&quot; title=&quot;Don pour les critiques&quot;&gt;Don pour les critiques&lt;/a&gt; et les dons qui l’int&#232;grent dans leurs conditions. Ces dons fonctionnent uniquement avec l’arme de pr&#233;dilection du kensai. Ce pouvoir remplace l’&lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ARCANE&quot; title=&quot;Le magus&quot;&gt;arcane&lt;/a&gt; de magus du niveau 9.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;R&#233;flexes sup&#233;rieurs (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;flexes_sup&#233;rieurs_Ext_8&quot; href=&quot;#R&#233;flexes_sup&#233;rieurs_Ext_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, le kensai peut faire un nombre d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; &#233;gal &#224; son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; au cours du m&#234;me round (1 au minimum). Cet effet se cumule avec le don &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-R&#233;flexes.html&quot; title=&quot;Attaques r&#233;flexes&quot;&gt;Attaque r&#233;flexe&lt;/a&gt;. Ce pouvoir remplace science du &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#SOUVENIRMAGIQUE&quot; title=&quot;Le magus&quot;&gt;souvenir magique&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Concentration iaijutsu (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Concentration_iaijutsu_Ext_9&quot; href=&quot;#Concentration_iaijutsu_Ext_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 13, le kensai agit pendant le &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Roundsurprise.html&quot; title=&quot;round de surprise&quot;&gt;round de surprise&lt;/a&gt; et d&#233;gaine par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. En revanche, il est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Prisaud&#233;pourvu.html&quot; title=&quot;Pris au d&#233;pourvu&quot;&gt;pris au d&#233;pourvu&lt;/a&gt; jusqu’&#224; ce qu’il agisse. Lors d’un round de surprise ou quand il attaque un adversaire pris au d&#233;pourvu, il ajoute son modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; aux d&#233;g&#226;ts de son arme de pr&#233;dilection (0 au minimum). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ARMURELOURDE&quot; title=&quot;Le magus&quot;&gt;armure lourde&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;tre du iaijutsu (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;tre_du_iaijutsu_Ext_10&quot; href=&quot;#Ma&#238;tre_du_iaijutsu_Ext_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 19, le kensai fait automatiquement un 20 naturel aux jets d’&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; et il n’est jamais &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Surprise.html&quot; title=&quot;surpris&quot;&gt;surpris&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#ACCESAUXSORTSSUPERIEUR&quot; title=&quot;Le magus&quot;&gt;acc&#232;s aux sorts sup&#233;rieur&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;trise des armes (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;trise_des_armes_Ext_11&quot; href=&quot;#Ma&#238;trise_des_armes_Ext_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, le kensai obtient &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#MAITRISEDESARMES&quot; title=&quot;Le guerrier&quot;&gt;ma&#238;trise des armes&lt;/a&gt; pour son arme de pr&#233;dilection (comme le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt;). Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Magus.html#MAGUSULTIME&quot; title=&quot;Le magus&quot;&gt;magus ultime&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Arcanes de magus conseill&#233;s&lt;a class=&quot;headeranchor&quot; id=&quot;Arcanes_de_magus_conseill&#233;s_12&quot; href=&quot;#Arcanes_de_magus_conseill&#233;s_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Voici les &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes.html&quot; title=&quot;Les arcanes du magus&quot;&gt;arcanes&lt;/a&gt; de magus qui viennent compl&#233;ter l’arch&#233;type de kensai : &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Attaqueravecprescience.html&quot; title=&quot;attaquer avec prescience&quot;&gt;attaquer avec prescience&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Boucliermagique.html&quot; title=&quot;bouclier magique&quot;&gt;bouclier magique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Concentre.html&quot; title=&quot;concentr&#233; (arcane)&quot;&gt;concentr&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Coupprecis.html&quot; title=&quot;coup pr&#233;cis&quot;&gt;coup pr&#233;cis&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Defendreavecprescience.html&quot; title=&quot;d&#233;fendre avec prescience&quot;&gt;d&#233;fendre avec prescience&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Arcanes#Frappecritique.html&quot; title=&quot;frappe critique&quot;&gt;frappe critique&lt;/a&gt;.
